import unittest
from ledger import total_cents


class LedgerTests(unittest.TestCase):
    def test_one_unit(self):
        self.assertEqual(total_cents([{"unit_cents": 125, "quantity": 1}]), 125)

    def test_empty(self):
        self.assertEqual(total_cents([]), 0)


if __name__ == "__main__":
    unittest.main()
